con:testSuite.con:setupScript:
import com.eviware.soapui.impl.wsdl.teststeps.WsdlTestRequestStep
import com.eviware.soapui.impl.support.AbstractHttpRequest
import com.eviware.soapui.config.CredentialsConfig

// Enter your existing HTTP Basic login credentials here
def httpUser = "TEMADEV1"
def httpPass = "TBs@Dev162*"

for (testCase in testSuite.getTestCaseList()) {
    for (testStep in testCase.getTestStepList()) {

        if (testStep instanceof WsdlTestRequestStep) {

            def request = testStep.getTestRequest()

            request.addBasicAuthenticationProfile("Basic")
            request.setUsername(httpUser)
            request.setPassword(httpPass)
            request.setPreemptive(true)

            request.setSelectedAuthProfileAndAuthType(
                AbstractHttpRequest.BASIC_AUTH_PROFILE,
                CredentialsConfig.AuthType.PREEMPTIVE
            )

            log.info("Basic Authentication configured for: " + testStep.getLabel())
        }
    }
}
